return items.map(item => {
  const jid = item.json.body.data.key.remoteJid;
  const num = jid.replace('@s.whatsapp.net', '');
  const sem9 = (num.length === 13 && num.startsWith('55') && num[4] === '9')
    ? num.slice(0, 4) + num.slice(5)
    : num;
  const com9 = (num.length === 12 && num.startsWith('55'))
    ? num.slice(0, 4) + '9' + num.slice(4)
    : num;
  return {
    json: {
      original: num + '@s.whatsapp.net',
      com9: com9 + '@s.whatsapp.net',
      sem9: sem9 + '@s.whatsapp.net'
    }
  };
});

const texto = ($json.msg || '').toLowerCase();
const keywords = ['preço', 'preco', 'valor', 'quanto', 'orçamento', 'orcamento', 'tabela'];
const pedidoPreco = keywords.some(k => texto.includes(k));
const contadorAtual = Number($json.contador_de_preco || 0);
return [{
  json: {
    ...$json,
    pedidoPreco,
    contadorAntes: contadorAtual,
    contadorDepois: pedidoPreco ? contadorAtual + 1 : contadorAtual
  }
}];

const text = $input.first().json.output || items[0].json?.text || '';
const parts = text
  .split(/(?<!\b(?:Dr|Dra|Sr|Sra|Prof|Ms|Mr|Mrs)\\.)(?<=\\.)\\s+/)
  .map(p => p.replace(/([?!])\\s+/g, '$1\n').trim())
  .filter(p => p.length > 0);
return parts.map(p => ({ json: { text: p } }));
